1	//! Merged release commits whose release never finished.
2	//!
3	//! A release publishes to the registries first, creates a package's tag only after they confirm, and publishes its
4	//! GitHub release last. So a release is finished exactly when every package in its committed decision has its tag and
5	//! every package released to GitHub has a published release. Both are cheap to read, which lets this look at old
6	//! release commits without planning from them.
7	
8	use std::collections::BTreeSet;
9	use std::path::Path;
10	
11	use callisto_model::{CommandRunner, CommitSha, PublishTarget, ReleaseDecisionV1, ReleasePackageId, TagName, Version};
12	
13	use super::github::{github_release_for_tag, GitHubReleaseLookup};
14	use super::provider::ProviderContext;
15	use crate::commands::release_decision::{has_dispatchable_target, tag_of_version, workspace_package};
16	use crate::{DependencyResolver, GraphError, TagIndex, Workspace};
17	
18	/// A merged release the committed decision describes that has not finished.
19	#[derive(Clone, Debug, PartialEq, Eq)]
20	pub struct PendingRelease {
21	    /// The release commit: the source to release.
22	    pub source: CommitSha,
23	    pub packages: Vec<(ReleasePackageId, Version)>,
24	    /// What the release should have produced and did not: tags, and GitHub releases that are missing or still drafts.
25	    pub missing: Vec<String>,
26	}
27	
28	/// The unfinished releases among the last `limit` commits on HEAD's first-parent line that wrote the decision at
29	/// `decision_path`, oldest first. Scanning newest to oldest stops at the first finished release, since releases are
30	/// sequential and anything older was released before it. With `from`, only that release commit and newer ones count.
31	pub fn pending_releases<R: CommandRunner, D: DependencyResolver>(
32	    workspace: &Workspace<'_, R, D>,
33	    decision_path: &Path,
34	    limit: usize,
35	    from: Option<&CommitSha>,
36	) -> Result<Vec<PendingRelease>, GraphError> {
37	    let git = workspace.git_access();
38	    let mut commits = git.first_parent_commits_touching(&[decision_path.to_path_buf()])?;
39	    if let Some(from) = from {
40	        let at = commits
41	            .iter()
42	            .position(|commit| commit == from.as_str())
43	            .ok_or_else(|| GraphError::ReleaseInvariant {
44	                detail: format!("`{}` is not a release commit on this branch", from.as_str()),
45	            })?;
46	        commits.truncate(at + 1);
47	    }
48	
49	    let tags = workspace.tags()?;
50	    let forge = workspace
51	        .config
52	        .product_release
53	        .as_ref()
54	        .and_then(|release| release.forge_repository.as_ref())
55	        .map(|repository| format!("{}/{}", repository.owner(), repository.repo()));
56	    let context = ProviderContext::new(&workspace.root, workspace.runner, None);
57	
58	    let mut pending = Vec::new();
59	    for commit in commits.into_iter().take(limit) {
60	        let source = CommitSha::parse(&commit).map_err(|error| GraphError::ReleaseInvariant {
61	            detail: format!("git named the release commit `{commit}`: {error}"),
62	        })?;
63	        let Some(text) = git.read_at(&commit, decision_path)? else {
64	            continue;
65	        };
66	        let decision: ReleaseDecisionV1 =
67	            serde_json::from_str(&text).map_err(|error| GraphError::ReleaseDecisionDecode {
68	                path: decision_path.to_path_buf(),
69	                message: error.to_string(),
70	            })?;
71	        let missing = release_gaps(workspace, &context, tags, forge.as_deref(), &decision);
72	        if missing.is_empty() {
73	            break;
74	        }
75	        pending.push(PendingRelease {
76	            source,
77	            packages: decision
78	                .entries
79	                .iter()
80	                .map(|entry| (entry.package.clone(), entry.target_version.clone()))
81	                .collect(),
82	            missing,
83	        });
84	    }
85	    pending.reverse();
86	    Ok(pending)
87	}
88	
89	/// What `decision`'s release should have produced and has not.
90	fn release_gaps<R: CommandRunner, D: DependencyResolver>(
91	    workspace: &Workspace<'_, R, D>,
92	    context: &ProviderContext<'_>,
93	    tags: &TagIndex,
94	    forge: Option<&str>,
95	    decision: &ReleaseDecisionV1,
96	) -> Vec<String> {
97	    let mut gaps = Vec::new();
98	    let mut seen = BTreeSet::new();
99	    for entry in &decision.entries {
100	        // A package that is gone, or no longer published anywhere, cannot be released now.
101	        let Some(package) = workspace_package(workspace, &entry.package) else {
102	            continue;
103	        };
104	        if !has_dispatchable_target(package) {
105	            continue;
106	        }
107	        let expected = tags.template(&package.id).render(&entry.target_version).to_string();
108	        // A package with several identities has one tag.
109	        if !seen.insert(expected.clone()) {
110	            continue;
111	        }
112	        let Some(tag) = tag_of_version(tags, &package.id, &entry.target_version) else {
113	            gaps.push(format!("tag {expected}"));
114	            continue;
115	        };
116	        if package.publish_to.contains(&PublishTarget::GitHubRelease)
117	            && let (Some(repository), Ok(name)) = (forge, TagName::parse(&tag))
118	            && !release_is_published(workspace, context, repository, &name)
119	        {
120	            gaps.push(format!("published GitHub release for {tag}"));
121	        }
122	    }
123	    gaps
124	}
125	
126	/// A release that cannot be read counts as not published, so the release is rerun: that adopts what already landed.
127	fn release_is_published<R: CommandRunner, D: DependencyResolver>(
128	    workspace: &Workspace<'_, R, D>,
129	    context: &ProviderContext<'_>,
130	    repository: &str,
131	    tag: &TagName,
132	) -> bool {
133	    matches!(
134	        github_release_for_tag(&workspace.root, workspace.runner, context.sleeper(), repository, tag),
135	        Ok(GitHubReleaseLookup::Found(value)) if value.get("draft").and_then(serde_json::Value::as_bool) != Some(true)
136	    )
137	}
