201	/// The version `manifest` holds at `rev`, resolving a workspace-inherited one. A manifest that is absent, does not
202	/// parse or declares no version there gives `None`; a failing git read is an error.
203	fn effective_version_at(
204	    reads: &RevReads<'_, '_>,
205	    rev: &str,
206	    manifest: &ManifestDecl,
207	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
208	    // `read_effective_version` reports manifest errors only, so a git failure is held here and returned after.
209	    let git_failure: RefCell<Option<GraphError>> = RefCell::new(None);
210	    let mut read = |path: &std::path::Path| -> Result<Option<String>, ManifestError> {
211	        Ok(reads.text(rev, path).unwrap_or_else(|error| {
212	            git_failure.borrow_mut().get_or_insert(error);
213	            None
214	        }))
215	    };
216	    let found = match read(&manifest.path)? {
217	        Some(source) => read_effective_version(
218	            manifest.format,
219	            &source,
220	            &manifest.path,
221	            &mut WorkspaceReads::default(),
222	            &mut read,
223	        )
224	        .ok()
225	        .flatten(),
226	        None => None,
227	    };
228	    match git_failure.into_inner() {
229	        Some(error) => Err(error),
230	        None => Ok(found),
231	    }
232	}
